import './App.css'; 
import React from 'react';


function About() {

  return (
    <div>
      <h1 className="text-4xl font-bold text-center pt-8 pb-8">About FlaskCart 🍓</h1>
      <p>After many converstation about "what's in the fridge?" or "what do we need to buy?" we created FlaskCart to help you manage your pantry and create delicious recipes with the ingredients you have on hand.</p>
    </div>
  );
}

export default About;
